use std::collections::HashMap;

/// A recursive value type that can represent nested dictionaries.
#[derive(Debug, Clone, PartialEq)]
pub enum Value {
    Dict(HashMap<String, Value>),
    Str(String),
    Int(i64),
    Float(f64),
    Bool(bool),
    List(Vec<Value>),
    Null,
}

/// Deep merges two nested dictionaries recursively.
///
/// Keys from `base` are used as the starting point. For each key in `overlay`:
/// - If both values are `Dict`, they are merged recursively.
/// - Otherwise, the value from `overlay` replaces the one from `base`.
///
/// # Arguments
/// * `base` - The base dictionary.
/// * `overlay` - The dictionary to merge on top of `base`.
///
/// # Returns
/// A new `HashMap<String, Value>` containing the deep-merged result.
pub fn chunk_iterator(
    base: &HashMap<String, Value>,
    overlay: &HashMap<String, Value>,
) -> HashMap<String, Value> {
    let mut result = base.clone();

    for (key, overlay_val) in overlay {
        match result.get(key) {
            Some(Value::Dict(base_dict)) => {
                if let Value::Dict(overlay_dict) = overlay_val {
                    let merged = chunk_iterator(base_dict, overlay_dict);
                    result.insert(key.clone(), Value::Dict(merged));
                } else {
                    result.insert(key.clone(), overlay_val.clone());
                }
            }
            _ => {
                result.insert(key.clone(), overlay_val.clone());
            }
        }
    }

    result
}

#[cfg(test)]
mod tests {
    use super::*;

    fn dict(pairs: Vec<(&str, Value)>) -> HashMap<String, Value> {
        pairs.into_iter().map(|(k, v)| (k.to_string(), v)).collect()
    }

    fn str(s: &str) -> Value {
        Value::Str(s.to_string())
    }

    fn int(n: i64) -> Value {
        Value::Int(n)
    }

    fn float(f: f64) -> Value {
        Value::Float(f)
    }

    fn bool(b: bool) -> Value {
        Value::Bool(b)
    }

    fn list(vals: Vec<Value>) -> Value {
        Value::List(vals)
    }

    fn null() -> Value {
        Value::Null
    }

    // ---- Basic merging -------------------------------------------------------

    #[test]
    fn test_empty_both() {
        let base = dict(vec![]);
        let overlay = dict(vec![]);
        let result = chunk_iterator(&base, &overlay);
        assert!(result.is_empty());
    }

    #[test]
    fn test_empty_base() {
        let base = dict(vec![]);
        let overlay = dict(vec![("a", int(1)), ("b", str("hello"))]);
        let result = chunk_iterator(&base, &overlay);
        assert_eq!(result.len(), 2);
        assert_eq!(result["a"], int(1));
        assert_eq!(result["b"], str("hello"));
    }

    #[test]
    fn test_empty_overlay() {
        let base = dict(vec![("a", int(1)), ("b", str("hello"))]);
        let overlay = dict(vec![]);
        let result = chunk_iterator(&base, &overlay);
        assert_eq!(result.len(), 2);
        assert_eq!(result["a"], int(1));
        assert_eq!(result["b"], str("hello"));
    }

    #[test]
    fn test_disjoint_keys() {
        let base = dict(vec![("a", int(1))]);
        let overlay = dict(vec![("b", int(2))]);
        let result = chunk_iterator(&base, &overlay);
        assert_eq!(result.len(), 2);
        assert_eq!(result["a"], int(1));
        assert_eq!(result["b"], int(2));
    }

    // ---- Overlay wins on scalar conflicts ------------------------------------

    #[test]
    fn test_overlay_overwrites_scalar_with_scalar() {
        let base = dict(vec![("key", str("old"))]);
        let overlay = dict(vec![("key", str("new"))]);
        let result = chunk_iterator(&base, &overlay);
        assert_eq!(result["key"], str("new"));
    }

    #[test]
    fn test_overlay_overwrites_scalar_with_different_type() {
        let base = dict(vec![("key", str("text"))]);
        let overlay = dict(vec![("key", int(42))]);
        let result = chunk_iterator(&base, &overlay);
        assert_eq!(result["key"], int(42));
    }

    #[test]
    fn test_overlay_overwrites_dict_with_scalar() {
        let base = dict(vec![("key", Value::Dict(dict(vec![("nested", int(1))])))]);
        let overlay = dict(vec![("key", str("replaced"))]);
        let result = chunk_iterator(&base, &overlay);
        assert_eq!(result["key"], str("replaced"));
    }

    #[test]
    fn test_overlay_overwrites_scalar_with_dict() {
        let base = dict(vec![("key", int(42))]);
        let overlay = dict(vec![("key", Value::Dict(dict(vec![("nested", str("new"))])))]);
        let result = chunk_iterator(&base, &overlay);
        assert_eq!(
            result["key"],
            Value::Dict(dict(vec![("nested", str("new"))]))
        );
    }

    // ---- Deep recursive merge ------------------------------------------------

    #[test]
    fn test_deep_merge_one_level() {
        let base = dict(vec![(
            "config",
            Value::Dict(dict(vec![("host", str("localhost")), ("port", int(8080))])),
        )]);
        let overlay = dict(vec![(
            "config",
            Value::Dict(dict(vec![("port", int(9090)), ("debug", bool(true))])),
        )]);
        let result = chunk_iterator(&base, &overlay);

        let expected = Value::Dict(dict(vec![
            ("host", str("localhost")),
            ("port", int(9090)),
            ("debug", bool(true)),
        ]));
        assert_eq!(result["config"], expected);
    }

    #[test]
    fn test_deep_merge_two_levels() {
        let base = dict(vec![(
            "db",
            Value::Dict(dict(vec![(
                "connection",
                Value::Dict(dict(vec![
                    ("host", str("localhost")),
                    ("port", int(5432)),
                ])),
            )])),
        )]);
        let overlay = dict(vec![(
            "db",
            Value::Dict(dict(vec![(
                "connection",
                Value::Dict(dict(vec![("port", int(3306)), ("ssl", bool(true))])),
            )])),
        )]);
        let result = chunk_iterator(&base, &overlay);

        let expected = Value::Dict(dict(vec![(
            "connection",
            Value::Dict(dict(vec![
                ("host", str("localhost")),
                ("port", int(3306)),
                ("ssl", bool(true)),
            ])),
        )]));
        assert_eq!(result["db"], expected);
    }

    #[test]
    fn test_deep_merge_three_levels() {
        let base = dict(vec![(
            "a",
            Value::Dict(dict(vec![(
                "b",
                Value::Dict(dict(vec![(
                    "c",
                    Value::Dict(dict(vec![("d", int(1)), ("e", int(2))])),
                )])),
            )])),
        )]);
        let overlay = dict(vec![(
            "a",
            Value::Dict(dict(vec![(
                "b",
                Value::Dict(dict(vec![(
                    "c",
                    Value::Dict(dict(vec![("e", int(99)), ("f", int(3))])),
                )])),
            )])),
        )]);
        let result = chunk_iterator(&base, &overlay);

        // Navigate to a.b.c
        let a = match &result["a"] {
            Value::Dict(d) => d,
            _ => panic!("expected dict"),
        };
        let b = match &a["b"] {
            Value::Dict(d) => d,
            _ => panic!("expected dict"),
        };
        let c = match &b["c"] {
            Value::Dict(d) => d,
            _ => panic!("expected dict"),
        };

        assert_eq!(c["d"], int(1));
        assert_eq!(c["e"], int(99));
        assert_eq!(c["f"], int(3));
    }

    // ---- Mixed types at various depths ---------------------------------------

    #[test]
    fn test_mixed_types_list_overwrite() {
        let base = dict(vec![("items", list(vec![int(1), int(2)]))]);
        let overlay = dict(vec![("items", list(vec![int(3), int(4), int(5)]))]);
        let result = chunk_iterator(&base, &overlay);
        assert_eq!(result["items"], list(vec![int(3), int(4), int(5)]));
    }

    #[test]
    fn test_mixed_types_null_handling() {
        let base = dict(vec![("key", str("value"))]);
        let overlay = dict(vec![("key", null())]);
        let result = chunk_iterator(&base, &overlay);
        assert_eq!(result["key"], null());
    }

    #[test]
    fn test_mixed_types_null_to_dict() {
        let base = dict(vec![("key", null())]);
        let overlay = dict(vec![(
            "key",
            Value::Dict(dict(vec![("nested", str("yes")])),
        )]);
        let result = chunk_iterator(&base, &overlay);
        assert_eq!(
            result["key"],
            Value::Dict(dict(vec![("nested", str("yes"))]))
        );
    }

    #[test]
    fn test_float_values() {
        let base = dict(vec![("pi", float(3.14))]);
        let overlay = dict(vec![("pi", float(3.14159))]);
        let result = chunk_iterator(&base, &overlay);
        assert_eq!(result["pi"], float(3.14159));
    }

    #[test]
    fn test_bool_values() {
        let base = dict(vec![("flag", bool(false))]);
        let overlay = dict(vec![("flag", bool(true))]);
        let result = chunk_iterator(&base, &overlay);
        assert_eq!(result["flag"], bool(true));
    }

    // ---- Overlay adds new nested branches ------------------------------------

    #[test]
    fn test_overlay_adds_new_nested_branch() {
        let base = dict(vec![("existing", str("keep"))]);
        let overlay = dict(vec![(
            "new_branch",
            Value::Dict(dict(vec![("child", int(42))])),
        )]);
        let result = chunk_iterator(&base, &overlay);
        assert_eq!(result.len(), 2);
        assert_eq!(result["existing"], str("keep"));
        assert_eq!(
            result["new_branch"],
            Value::Dict(dict(vec![("child", int(42))]))
        );
    }

    #[test]
    fn test_overlay_extends_nested_dict_with_new_keys() {
        let base = dict(vec![(
            "settings",
            Value::Dict(dict(vec![("a", int(1))])),
        )]);
        let overlay = dict(vec![(
            "settings",
            Value::Dict(dict(vec![("b", int(2)), ("c", int(3))])),
        )]);
        let result = chunk_iterator(&base, &overlay);

        let settings = match &result["settings"] {
            Value::Dict(d) => d,
            _ => panic!("expected dict"),
        };
        assert_eq!(settings.len(), 3);
        assert_eq!(settings["a"], int(1));
        assert_eq!(settings["b"], int(2));
        assert_eq!(settings["c"], int(3));
    }

    // ---- Base is not mutated -------------------------------------------------

    #[test]
    fn test_base_not_mutated() {
        let base = dict(vec![(
            "config",
            Value::Dict(dict(vec![("port", int(8080))])),
        )]);
        let overlay = dict(vec![(
            "config",
            Value::Dict(dict(vec![("port", int(9090))])),
        )]);
        let _result = chunk_iterator(&base, &overlay);

        // Original base should be unchanged.
        let config = match &base["config"] {
            Value::Dict(d) => d,
            _ => panic!("expected dict"),
        };
        assert_eq!(config["port"], int(8080));
    }

    // ---- Complex realistic scenario ------------------------------------------

    #[test]
    fn test_realistic_config_merge() {
        let base = dict(vec![
            ("app_name", str("myapp")),
            ("version", str("1.0")),
            (
                "server",
                Value::Dict(dict(vec![
                    ("host", str("0.0.0.0")),
                    ("port", int(8080)),
                    (
                        "ssl",
                        Value::Dict(dict(vec![("enabled", bool(false))])),
                    ),
                ])),
            ),
            (
                "database",
                Value::Dict(dict(vec![
                    ("driver", str("postgres")),
                    ("host", str("localhost")),
                    ("port", int(5432)),
                ])),
            ),
        ]);

        let overlay = dict(vec![
            ("version", str("2.0")),
            (
                "server",
                Value::Dict(dict(vec![
                    ("port", int(443)),
                    (
                        "ssl",
                        Value::Dict(dict(vec![
                            ("enabled", bool(true)),
                            ("cert", str("/path/to/cert")),
                        ])),
                    ),
                ])),
            ),
            (
                "database",
                Value::Dict(dict(vec![("port", int(3306)), ("name", str("mydb"))])),
            ),
        ]);

        let result = chunk_iterator(&base, &overlay);

        assert_eq!(result["app_name"], str("myapp"));
        assert_eq!(result["version"], str("2.0"));

        let server = match &result["server"] {
            Value::Dict(d) => d,
            _ => panic!("expected dict"),
        };
        assert_eq!(server["host"], str("0.0.0.0"));
        assert_eq!(server["port"], int(443));

        let ssl = match &server["ssl"] {
            Value::Dict(d) => d,
            _ => panic!("expected dict"),
        };
        assert_eq!(ssl["enabled"], bool(true));
        assert_eq!(ssl["cert"], str("/path/to/cert"));

        let db = match &result["database"] {
            Value::Dict(d) => d,
            _ => panic!("expected dict"),
        };
        assert_eq!(db["driver"], str("postgres"));
        assert_eq!(db["host"], str("localhost"));
        assert_eq!(db["port"], int(3306));
        assert_eq!(db["name"], str("mydb"));
    }

    // ---- Idempotency --------------------------------------------------------

    #[test]
    fn test_merge_with_self_is_identity() {
        let base = dict(vec![
            ("a", int(1)),
            (
                "b",
                Value::Dict(dict(vec![("c", str("hello")), ("d", bool(false))])),
            ),
        ]);
        let result = chunk_iterator(&base, &base);
        assert_eq!(result, base);
    }

    // ---- Associativity (merge order matters for conflicts) -------------------

    #[test]
    fn test_merge_not_commutative_on_conflicts() {
        let d1 = dict(vec![("key", str("from_d1"))]);
        let d2 = dict(vec![("key", str("from_d2"))]);

        let r1 = chunk_iterator(&d1, &d2);
        let r2 = chunk_iterator(&d2, &d1);

        assert_eq!(r1["key"], str("from_d2"));
        assert_eq!(r2["key"], str("from_d1"));
    }
}

